import '../../features/intelligence/domain/intelligence_library.dart';

/// Arabic digital-risk reference entries mapped to canonical stable IDs.
class ArabicIntelligenceContent {
  ArabicIntelligenceContent._();
  static const Map<String, Map<String, String>> _data = {
    'url-http': {'title':'اتصال HTTP غير مشفّر','signal':'يبدأ عنوان الموقع بـ http:// بدلاً من https://.','meaning':'لا يستخدم الاتصال بروتوكول TLS لحماية البيانات أثناء النقل. وقد تُكشف المعلومات أو تُعدّل عبر الشبكة.','action':'لا تُدخل كلمات المرور أو بيانات الدفع. انتقل إلى موقع المؤسسة عبر إشارة مرجعية موثوقة أو عنوان تحققت منه بشكل مستقل.','limit':'يحمي HTTPS الاتصال، لكنه لا يثبت أصالة الموقع نفسه.'},
    'url-userinfo': {'title':'معلومات مضللة داخل عنوان URL','signal':'يتضمن عنوان URL نصاً قبل الرمز @، مثل https://trusted.example@unknown.example/.','meaning':'يتعامل المتصفح مع النص بعد الرمز @ على أنه اسم المضيف. وقد يصرف النص الذي يبدو موثوقاً قبله الانتباه عن الوجهة الفعلية.','action':'تحقّق من اسم المضيف الفعلي بعد @ ومن النطاق المسجّل قبل المتابعة.','limit':'وجود معلومات مستخدم في عنوان URL أمر غير معتاد، لكنه لا يثبت وحده وجود نية ضارة.'},
    'url-punycode': {'title':'نطاق دولي أو Punycode','signal':'يحتوي اسم المضيف على xn-- أو على محارف متشابهة بصرياً.','meaning':'قد تستخدم أسماء النطاقات الدولية محارف من أنظمة كتابة مختلفة تشبه الحروف اللاتينية.','action':'تحقّق من التهجئة الدقيقة ومالك النطاق عبر مصدر موثوق. لا تعتمد على الشعار أو الاسم الظاهر وحدهما.','limit':'تستخدم مواقع شرعية كثيرة أسماء نطاقات دولية.'},
    'url-subdomains': {'title':'سلسلة متداخلة من النطاقات الفرعية','signal':'يحتوي اسم المضيف على مستويات متعددة، مثل login.account.example.invalid.','meaning':'ليس من الضروري أن يكون النطاق المسجّل أول كلمة مألوفة في العنوان. وقد يضع المهاجم اسم علامة تجارية في نطاق فرعي يتحكم به.','action':'اقرأ اسم المضيف من اليمين إلى اليسار، وحدّد النطاق المسجّل، ثم تحقّق منه بشكل مستقل.','limit':'تُستخدم سلاسل النطاقات الفرعية الطويلة أيضاً لأغراض مشروعة.'},
    'message-urgency': {'title':'الاستعجال والضغط','signal':'تطلب الرسالة إجراءً فورياً أو تهدد بإغلاق الحساب أو تفرض مهلة مصطنعة.','meaning':'يعيق الضغط التحقق المستقل ويدفع المستلم إلى التصرف دون تفكير.','action':'توقّف قليلاً. تواصل مع المؤسسة عبر تطبيق أو موقع أو رقم رسمي تعرفه، وليس عبر بيانات الاتصال الواردة في الرسالة.','limit':'قد تظهر عبارات الاستعجال في رسائل مشروعة أيضاً؛ فالسياق مهم.'},
    'message-credentials': {'title':'طلب كلمة مرور أو رمز لمرة واحدة','signal':'يطلب المرسل كلمة مرور أو رمز OTP أو رمز استرداد أو الموافقة على تسجيل دخول غير متوقع.','meaning':'قد تمنح هذه الأسرار أو الموافقات إمكانية الوصول إلى الحساب أو السماح بمعاملة.','action':'لا تكشف كلمات المرور أو رموز OTP أبداً. ارفض طلبات الموافقة غير المتوقعة وتواصل مع الخدمة عبر قناة رسمية.','limit':'يشير تطابق الكلمات المفتاحية إلى موضوع الرسالة فقط، ولا يحدد هوية المرسل أو نيته.'},
    'message-payment': {'title':'طلب دفع أو استرداد غير متوقع','signal':'تطلب الرسالة تحويلاً أو رسوم معالجة أو ترتيب استرداد أو دفعاً للحصول على منفعة.','meaning':'قد تُستخدم تعليمات مالية غير متوقعة لتحويل الأموال أو جمع بيانات الدفع.','action':'تحقّق بشكل مستقل من المستفيد والمبلغ والسبب عبر قناة موثوقة منفصلة قبل اتخاذ أي إجراء.','limit':'تظهر إشارات الدفع أيضاً في الفواتير والإشعارات المشروعة.'},
    'qr-payment': {'title':'طلب دفع عبر رمز QR','signal':'يستخدم محتوى QR مخطط دفع مثل upi://pay.','meaning':'قد يجهّز المسح دفعة لمستفيد. لا يثبت رمز QR هوية المستفيد أو صحة المبلغ.','action':'تحقّق من اسم المستفيد ومعرّف UPI والمبلغ في تطبيق الدفع قبل التأكيد. ألغِ العملية عند وجود أي اختلاف.','limit':'محتوى الدفع ليس احتيالاً بحد ذاته؛ تحقّق من تفاصيل المعاملة.'},
    'qr-action': {'title':'رمز QR يتضمن رابطاً لإجراء','signal':'يحتوي رمز QR على إجراء ويب أو هاتف أو بريد إلكتروني أو SMS أو إجراء خاص بتطبيق.','meaning':'قد يفتح المحتوى عنواناً أو يملأ حقول إجراء مسبقاً عند معالجته في تطبيق آخر.','action':'راجع المحتوى المفكوك أولاً. لا تفتح روابط غير معروفة ولا تؤكد إجراءات معبأة مسبقاً دون تحقق.','limit':'لا يثبت نوع المحتوى وحده موثوقية المصدر.'},
    'account-mfa': {'title':'طلب مصادقة متعددة العوامل غير متوقع','signal':'تلقيت طلب موافقة على تسجيل الدخول أو رمزاً لمرة واحدة لم تطلبه.','meaning':'قد يحاول شخص ما تسجيل الدخول باستخدام اسم المستخدم وكلمة المرور، وقد يكون الرمز قد أُنشئ أيضاً عن طريق الخطأ.','action':'ارفض الطلب ولا تشارك الرمز. عند الحاجة، غيّر كلمة المرور عبر الخدمة الرسمية وراجع الجلسات النشطة.','limit':'الطلب غير المتوقع إشارة تحذير، وليس دليلاً قاطعاً على اختراق الحساب.'},
  };
  static IntelligenceEntry localize(IntelligenceEntry item, String code) {
    if (code != 'ar') return item;
    final value = _data[item.id];
    if (value == null) return item;
    return IntelligenceEntry(
      id: item.id,
      title: value['title']!,
      category: item.category,
      signal: value['signal']!,
      meaning: value['meaning']!,
      action: value['action']!,
      limit: value['limit']!,
    );
  }
}
